// src/surface/host.ts
var COMPOSER_ID = "dock.composer";
var INPUT_ID = `${COMPOSER_ID}.line.input`;
var SurfaceHost = class {
  #surface;
  #focus = INPUT_ID;
  /** Opens the surface on `tern`, titled `title` (the tab's name until a program sets one), wearing `styles`. */
  constructor(tern, title, styles) {
    this.#surface = tern.open({ id: "hermes", mode: "inline", role: "omp.session", title });
    this.#surface.stylesheet("hermes-tern", styles);
  }
  /** Whether Tern dropped the surface or it was closed: it draws nothing more. */
  get closed() {
    return this.#surface.closed;
  }
  render(view) {
    this.#surface.render(view);
  }
  palette(palette) {
    this.#surface.palette(palette);
  }
  /** Gives the caret to `id` (or to none) now, sent even when it is already there. */
  focus(id) {
    this.#focus = id;
    this.#surface.focus(id);
  }
  /** Gives the caret to `id` when it is somewhere else: what each render does. */
  follow(id) {
    if (id !== this.#focus) {
      this.focus(id);
    }
  }
  reveal(id, at) {
    this.#surface.reveal(id, at);
  }
  scroll(id, to) {
    this.#surface.scroll(id, to);
  }
};

// src/surface/actions.ts
function cardRow(value) {
  const at = value.lastIndexOf(":");
  return [value.slice(0, at), value.slice(at + 1)];
}
var ACTIONS = {
  // A live connect card's Connect on an MCP row: the gateway installs it.
  "connect-approve": (value, cx) => cx.connect.approve(...cardRow(value)),
  // A connect card's Continue.
  "connect-continue": (value, cx) => cx.connect.continue(value),
  // A connect card's Authorize: the app's link in the browser.
  "connect-open": (value, cx) => cx.connect.open(...cardRow(value)),
  // A live connect card's Try again on a failed or expired link.
  "connect-retry": (value, cx) => cx.connect.retry(...cardRow(value)),
  // A live connect card's Skip on one app.
  "connect-skip": (value, cx) => cx.connect.skip(...cardRow(value)),
  "open-agent": (value, cx) => cx.openAgent(value),
  "open-process": (value, cx) => cx.openProcess(value),
  // A connect card's Authorize: the app's link in the browser.
  "open-url": (value, cx) => cx.openUrl(value)
};
var isActionName = (act) => Object.hasOwn(ACTIONS, act);
function onTernEvent(ev, cx) {
  if (ev.ev === "action" && ev.value && isActionName(ev.act)) {
    return ACTIONS[ev.act](ev.value, cx);
  }
  if (ev.ev === "focus" && ev.id === INPUT_ID && !cx.modal()) {
    cx.focusComposer();
  }
}

// src/surface/input.ts
async function runInput(input, { after, onError, onEvent, onKey: onKey2 }) {
  try {
    for await (const item3 of input) {
      if (item3.type === "key") {
        onKey2(item3.key);
      } else {
        onEvent(item3.event);
      }
      after();
    }
  } catch (error) {
    onError?.(error);
  }
}

